import{_ as a,H as t,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"26 | 为一家濒临破产的公司制定增长策略（下）","description":"","frontmatter":{},"headers":[{"level":2,"title":"回顾用户增长地图","slug":"回顾用户增长地图","link":"#回顾用户增长地图","children":[]},{"level":2,"title":"分析二级增长策略","slug":"分析二级增长策略","link":"#分析二级增长策略","children":[{"level":3,"title":"1.北极星指标&一级方向","slug":"_1-北极星指标-一级方向","link":"#_1-北极星指标-一级方向","children":[]},{"level":3,"title":"2.用户旅程&增长指标","slug":"_2-用户旅程-增长指标","link":"#_2-用户旅程-增长指标","children":[]},{"level":3,"title":"3.二级洞察","slug":"_3-二级洞察","link":"#_3-二级洞察","children":[]},{"level":3,"title":"4.二级机会","slug":"_4-二级机会","link":"#_4-二级机会","children":[]}]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"从0开始做增长/26-为一家濒临破产的公司制定增长策略（下）.md","filePath":"从0开始做增长/26-为一家濒临破产的公司制定增长策略（下）.md","lastUpdated":1779818163000}'),l={name:"从0开始做增长/26-为一家濒临破产的公司制定增长策略（下）.md"};function s(r,e,o,p,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_26-为一家濒临破产的公司制定增长策略-下" tabindex="-1">26 | 为一家濒临破产的公司制定增长策略（下） <a class="header-anchor" href="#_26-为一家濒临破产的公司制定增长策略-下" aria-label="Permalink to &quot;26 | 为一家濒临破产的公司制定增长策略（下）&quot;">​</a></h1><p>你好，我是刘津。</p><p>今天我们接上一讲内容，看看要如何围绕一级方向，通过用户增长地图为Karmaloop制定二级增长策略。</p><h2 id="回顾用户增长地图" tabindex="-1">回顾用户增长地图 <a class="header-anchor" href="#回顾用户增长地图" aria-label="Permalink to &quot;回顾用户增长地图&quot;">​</a></h2><p>我们先来回顾一下用户增长地图的内容，你还记得吗？这里一共有4点。</p><ol><li>北极星指标&amp;一级方向</li><li>用户旅程&amp;增长指标</li><li>二级洞察（正向&amp;负向）</li><li>二级机会</li></ol><p>现在，我会带着你逐一完成这些内容，告诉你要如何用这几点来分析案例。我建议在每个具体部分展开之前，你能够先按照自己的理解把它们写下来，然后再参考我的内容，这样更有助于你日后的实战。</p><h2 id="分析二级增长策略" tabindex="-1">分析二级增长策略 <a class="header-anchor" href="#分析二级增长策略" aria-label="Permalink to &quot;分析二级增长策略&quot;">​</a></h2><p>准备好了吗？现在我们来尝试分析Karmaloop的二级增长策略。</p><h3 id="_1-北极星指标-一级方向" tabindex="-1">1.北极星指标&amp;一级方向 <a class="header-anchor" href="#_1-北极星指标-一级方向" aria-label="Permalink to &quot;1.北极星指标&amp;一级方向&quot;">​</a></h3><p>第一步，是北极星指标和一级方向，我们已经通过上一讲的内容得出了结论。</p><p>根据上一讲的内容，Karmaloop现阶段的北极星指标是“用户量增长且盈利”；一级方向是“突出和强调潮牌定位”。</p><h3 id="_2-用户旅程-增长指标" tabindex="-1">2.用户旅程&amp;增长指标 <a class="header-anchor" href="#_2-用户旅程-增长指标" aria-label="Permalink to &quot;2.用户旅程&amp;增长指标&quot;">​</a></h3><p>第二步，是用户旅程和增长指标。</p><p>Karmaloop是个海外产品，你应该是没有用过，所以为了方便你理解，我会按照常规电商网站的流程来梳理。那么用户旅程和对应的增长指标可以分为5点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/b984391e20a7451d70177ea2fc763d48.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/b984391e20a7451d70177ea2fc763d48.png" alt=""></a></p><ul><li>被吸引：广告曝光及朋友推荐；</li><li>访问网站并注册：网站访问量、注册率；</li><li>选择商品并加入购物车：加车率；</li><li>支付：首次购买率、新用户平均订单金额；</li><li>持续购买：已有老用户数、老用户重复购买比例、老用户平均订单金额。</li></ul><p>通过表格，相信你能更清楚直观地看到这个用户旅程。</p><h3 id="_3-二级洞察" tabindex="-1">3.二级洞察 <a class="header-anchor" href="#_3-二级洞察" aria-label="Permalink to &quot;3.二级洞察&quot;">​</a></h3><p>接下来我们加入第三步，二级洞察。这里，我们要先回答一级洞察的核心内容，即 <strong>用户是谁？它的差异特征是什么？如何差异化地满足？</strong></p><p>通过上一篇文章的分析，得到的一级洞察是：用户是认可潮牌文化的小众群体，以及渴望潮流、渴望被认同的大众群体。应该通过强调潮牌地位的领先者来差异化的满足用户群体。</p><p>那么与这个一级洞察对应的二级洞察是什么呢？还记得之前讲过的正负双向洞察吗？这里就要用上了。</p><p>我们先来说正向二级洞察，因为优点比缺点更重要。还记得那五个关于二级洞察的参考问题吗？我把这五个问题与用户旅程对应，一一列在下面这个表格里供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/041b8b7947f8b2e0bdc68d1579b56077.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/041b8b7947f8b2e0bdc68d1579b56077.png" alt=""></a></p><p>对应的，我们可以以二级洞察参考问题为方向来得到正向二级洞察。这些洞察有的是来自前面的用户洞察，有的是来自于数据分析。数据分析可以是跟自己产品相关的，也可以是行业数据带来的启发。</p><p>现在我们再来看看负向的二级洞察。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/0571e95fdeb7ce5134619f33c6c91950.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/0571e95fdeb7ce5134619f33c6c91950.png" alt=""></a></p><p>表格里同样是根据负向二级洞察的参考问题来得到负向二级洞察。你可以自行查看。</p><h3 id="_4-二级机会" tabindex="-1">4.二级机会 <a class="header-anchor" href="#_4-二级机会" aria-label="Permalink to &quot;4.二级机会&quot;">​</a></h3><p>第四步，也是最重要的一步，我们需要结合正向的二级洞察和负向的二级洞察得到增长机会。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/ce37686cccbca124556f918686c58d90.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/ce37686cccbca124556f918686c58d90.png" alt=""></a></p><p>这里需要注意的是： <strong>所有的二级机会不管怎么做，都需要围绕一个核心</strong>，那就是突出潮牌精神，强化Karmaloop的潮牌领导地位，强调它的价值和文化。缺少了这个核心，再怎么做都只是机械的操作和执行，最终的效果自然也很难令人满意。</p><p>这就好像画匠和大师的区别，画匠虽然可以画其“形”，却无法画其“神”。我们学习增长案例， <strong>既要关注他们的操作手段，更重要的是要揣摩背后的核心精神</strong>，这些东西才是最重要的。而市面上总结的增长案例恰恰隐藏掉了这些关键的东西，只是把表面上的策略告诉你。所以你即便完全照做，也觉得效果并不好。</p><p>说这些是真心希望 <strong>大家不要太依赖具体的案例和操作</strong>，如果你不知道背后的思考路径，只是简单地模仿和复制，那其实和你想要快速见效的初衷反而会背道而驰。</p><p>总之，一级方向画布和用户增长地图给我们提供了清晰的框架，帮助我们明确大方向并做好重要的决策而不遗漏关键的内容。相信通过它们，以后不管再遇到什么案例，你都可以按照这个逻辑去梳理，而不是看着别人的“经验之谈”不知从何下手。</p><p>希望你可以多加练习，慢慢地，你就会融会贯通，看到市面上任何增长案例都能知道它从何处来，又能到何处去，因为你心中已经有了一个非常坚实的逻辑框架。</p><p>好了，到现在，最艰难的“拔高”的部分终于结束了，感谢你坚持到这里。从下一讲开始，我将为你讲解具体落地执行的部分。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/ebdcea46640d639f5662fba4fa1ba25a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%81%9A%E5%A2%9E%E9%95%BF/images/99660/ebdcea46640d639f5662fba4fa1ba25a.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>按照我教你的方法，复盘市面上的某个增长案例，找找感觉。</p><p>欢迎把你的思考和疑问通过留言分享出来，与我和其他同学一起讨论。如果你觉得有所收获，也欢迎把文章分享给你的朋友。</p>',41)])])}const g=a(l,[["render",s]]);export{b as __pageData,g as default};
